function enter(s: GameState, scene: SceneBuilder): void {
  const arg = s.locArg;
  switch (arg) {
    case 'beauty':
      enterBeauty(s, scene);
      break;
    case 'food':
      enterFood(s, scene);
      break;
    case 'hardware':
      enterHardware(s, scene);
      break;
    case 'chemist':
      enterChemist(s, scene);
      break;
    case 'kiosk':
      enterKiosk(s, scene);
      break;
    case 'sexshop':
      enterSexshop(s, scene);
      break;
    case 'tech':
      enterTech(s, scene);
      break;
    case 'sports':
      enterSports(s, scene);
      break;
    case 'uni':
      enterUni(s, scene);
      break;
    case 'mothershop':
      enterMothershop(s, scene);
      break;
    case 'market':
      enterMarket(s, scene);
      break;
    case 'gad_store':
      enterGadStore(s, scene);
      break;
    case 'gad_market_hunter':
      enterGadMarketHunter(s, scene);
      break;
    case 'prost_shop':
      enterProstShop(s, scene);
      break;
    case 'experimental_trials':
      enterExperimentalTrials(s, scene);
      break;
    case 'cleanup':
      enterCleanup(s, scene);
      break;
    default:
      enterBeauty(s, scene);
      break;
  }
}

